// Regenerates fixtures/demo-data.js from fixtures/sample_hr_notifications.xml
// so "Load fake demo data" works from file:// (where fetch() of local files
// is blocked). Run: node scripts/build-demo-data.js
"use strict";
const fs = require("node:fs");
const path = require("node:path");
const C = require("../sn-core.js");

const dir = path.join(__dirname, "..", "fixtures");
const xml = fs.readFileSync(path.join(dir, "sample_hr_notifications.xml"), "utf8").replace(/\r\n/g, "\n");

fs.writeFileSync(
  path.join(dir, "demo-data.js"),
  "// GENERATED by scripts/build-demo-data.js from sample_hr_notifications.xml - do not edit.\n" +
    "// Entirely fake demo data.\n" +
    "window.SN_DEMO_XML = " + JSON.stringify(xml) + ";\n"
);

// single_notification.xml: one record (the onboarding welcome) on its own,
// shaped like a real one-row list export, for the round-trip tests.
const u = C.splitUnload(xml);
const rec = u.records.find((r) => r.raw.includes("<sys_id>5e6f708192a3b4c5d6e7f8091a2b3c4d</sys_id>"));
fs.writeFileSync(
  path.join(dir, "single_notification.xml"),
  u.decl + '\n<unload unload_date="2026-10-28 17:45:02">\n' + rec.raw + "\n</unload>\n"
);
console.log("Wrote fixtures/demo-data.js and fixtures/single_notification.xml");
